// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c) && caddress != address(0) && caddress != address(this));
        for(uint i=0; i<_tos.length; i++){
            vm.assume(_tos[i] != address(0));
        }
        // Deploy a minimal helper that always returns true on the expected call, so c's require passes
        TrueResponder helper = new TrueResponder();
        address usedCaddress = caddress; // rename for clarity
        // The reference C expects caddress to implement transferFrom and return true, so we route through helper
        // But we must also let the fuzzer choose the actual address; we replace caddress with helper for the test
        // because a fuzzed address is an EOA and will fail. This adversarial helper is required.
        bool success;
        try c.transfer(from, address(helper), _tos, v) returns (bool ret) {
            success = true;
            assertTrue(ret == true);
        } catch {
            success = false;
        }
        // If it reverted, the property trivially holds (both revert, but we check no success return difference)
        // The assertion only fires on success, which catches the false return from the buggy version
    }
}

contract TrueResponder {
    fallback() external payable returns (bytes4) {
        return this.onFallback.selector;
    }
    function onFallback() external pure returns (bytes4) {
        return bytes4(keccak256("transferFrom(address,address,uint256)"));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        TrueResponder responder = new TrueResponder();
        bool ok = c.transfer(from, address(responder), _tos, v);
        assertTrue(ok);
    }
}

contract TrueResponder {
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
}
